//////////////////////////////////////////////////////////////////////
//
//  ClothSolver.h - The cloth solver behind the generic solver contract
//  (simulation M3a)
//
//  Registered as "cloth.shell".  A rectangular sheet generated by the
//  solver (ClothModel.h) with a material record (ClothMaterial.h), pins,
//  analytic colliders and loads.  Modes: "bake" (BDF2 by default, Newton to
//  a stated residual) and "interactive" (backward Euler, at most a few
//  Newton iterations).  Publishes "surface" (mesh.v1: positions,
//  velocities, normals, fixed topology); offers the port "surface_state"
//  (the same payloads) and accepts "surface_load" (grid.v1 on the sheet's
//  vertex lattice: "pressure" in Pa and/or "traction", 3 components, Pa).
//  Honours imposed macro steps; deterministic; checkpoints are exact.
//  M7e (docs/SIMULATION_M7E_RESULTS.md): also offers "surface_mechanics"
//  (lumped masses, pins, force, Rayleigh coefficients) and
//  "surface_stiffness" (the projected elastic Hessian's upper blocks), and
//  accepts "surface_load_steps" (a partner's steps and their impulses: the
//  cloth then takes those steps by backward Euler with the macro step's
//  elasticity linearised at its start) and a per-vertex "force" (N) on
//  "surface_load".
//
//  Evidence is computed at Configure by running a fast subset of the
//  analytic validation cases (ClothValidation.h) for the configured
//  material, triangulation, bending model and integrator, memoised per
//  process.  "predictive" is requested only in bake mode without
//  colliders and air drag; the host derives the label from the cases.
//
//  Parameters and their defaults: docs/SIMULATION_M3A_RESULTS.md.
//
//  License Information: Please see the attached LICENSE.TXT file
//
//////////////////////////////////////////////////////////////////////

#ifndef RISE_SIMULATION_CLOTH_SOLVER_H
#define RISE_SIMULATION_CLOTH_SOLVER_H

#include "../SimulationSolver.h"
#include <string>

namespace RISE { namespace Simulation {

//! Solver id of the cloth solver.
constexpr const char* ClothSolverId = "cloth.shell";

//! Registers the cloth solver factory under "cloth.shell".  Idempotent.
bool RegisterClothSolver(std::string& error);

} }

#endif
